"任何房间：主基地耐久 +{0}%。契合「防御」：守城时 {1} 名陶土守卫加入战斗。": "Orice cameră: durabilitatea Fortăreței +{0}%. Se potrivește cu „Apărare”: {1} străjeri de lut se alătură apărării.",
"任何房间：出征多带 {0} 件宝物。契合「防御」：武器：伤害 +{1}%，命中溅射并减速；其它：再多 {2} 名守卫。": "Orice cameră: +{0} relicve în expediții. Se potrivește cu „Apărare”: armele dau daune +{1}%, lovesc în zonă și încetinesc; celelalte primesc încă {2} străjeri.",
"任何房间：出征带回的物资 +{0}%。契合「运势」：物资再 +{1}%，每场战斗初始积分倍率 +{2}。": "Orice cameră: provizii aduse acasă +{0}%. Se potrivește cu „Noroc”: provizii încă +{1}%, multiplicatorul de puncte la start +{2} în fiecare luptă.",
"任何房间：出征视野 +{0}，初始积分倍率 +{1}。契合「运势 / 特殊」：出征地图一开始就全亮，积分倍率再 +{2}。": "Orice cameră: vizibilitate în expediție +{0}, multiplicatorul de puncte la start +{1}. Se potrivește cu „Noroc / Special”: harta expediției e complet dezvăluită de la început, multiplicator încă +{2}.",
"任何房间：出征部队攻击 +{0}%。契合「训练」：领袖出征得到的经验 +{1}%。": "Orice cameră: atacul trupelor în expediție +{0}%. Se potrivește cu „Antrenament”: EXP-ul Liderului din expediții +{1}%.",
"任何房间：出征部队生命 +{0}%。契合「医疗」：医院回复 +{1}%，领袖每天再回 {2}%。": "Orice cameră: viața trupelor în expediție +{0}%. Se potrivește cu „Medical”: vindecarea în spital +{1}%, liderul își reface încă {2}% pe zi.",
"任何房间：图纸掉率 +{0}%。契合「科幻」：基地每天 +{1} 灵魂碎片。": "Orice cameră: șansa de plan +{0}%. Se potrivește cu „SF”: baza +{1} Fragmente de Suflet pe zi.",
"任何房间：图纸掉率 +{0}%。契合「锻造」：打造时 {1}% 概率多得一件。": "Orice cameră: șansa de plan +{0}%. Se potrivește cu „Forjă”: {1}% șansă de încă o relicvă la făurire.",
"任何房间：基地每天 +{0} 灵魂碎片。契合「魔法」：基地每天再 +{1} 灵魂碎片。": "Orice cameră: baza +{0} Fragmente de Suflet pe zi. Se potrivește cu „Magie”: încă +{1} pe zi.",
"任何房间：基地每天 +{0} 物资。契合「后勤」：这个房间自己的效果 ×{1}。": "Orice cameră: baza +{0} provizii pe zi. Se potrivește cu „Logistică”: efectul propriu al acestei camere ×{1}.",
"任何房间：基地每天 +{0} 物资，领袖每天获得 {1} 经验。契合「后勤 / 自然」：这个房间自己的效果 ×{2}。": "Orice cameră: baza +{0} provizii pe zi, liderul primește {1} EXP pe zi. Se potrivește cu „Logistică / Natură”: efectul propriu al acestei camere ×{2}.",
"任何房间：宝物打造费用 -{0}%。契合「锻造 / 武器」：锻造：{1}% 概率品质 +{2}；武器：伤害 +{3}%。": "Orice cameră: costul făuririi relicvelor -{0}%. Se potrivește cu „Forjă / Armă”: la forjă, {1}% șansă de calitate +{2}; armele dau daune +{3}%.",
"任何房间：建造时间减半，建成返还 {0}% 物资。契合「奇观」：返还提高到 {1}%。": "Orice cameră: timp de construcție înjumătățit, {0}% din provizii returnate la final. Se potrivește cu „Minune”: returnarea crește la {1}%.",
"任何房间：所有防御塔伤害 +{0}%。契合「武器」：射程 +{1}，攻速 +{2}%。": "Orice cameră: toate turnurile de apărare dau daune +{0}%. Se potrivește cu „Armă”: rază +{1}, vit. de atac +{2}%.",
"任何房间：挖掘费用 -{0}%。契合「特殊」：所有建造少花 {1} 天。": "Orice cameră: costul săpatului -{0}%. Se potrivește cu „Special”: toate construcțiile durează cu {1} z. mai puțin.",
"任何房间：每场战斗初始积分倍率 +{0}。契合「锻造」：打造的宝物品质必定 +{1}。": "Orice cameră: multiplicatorul de puncte la start +{0} în fiecare luptă. Se potrivește cu „Forjă”: relicvele făurite au mereu calitate +{1}.",
"任何房间：领袖技能冷却少 {0} 个节点。契合「运势」：出征开局多带 {1} 个支援道具（至少转出「史诗」效果）。": "Orice cameră: reîncărcarea abilității liderului cu {0} opriri mai scurtă. Se potrivește cu „Noroc”: începi expedițiile cu {1} obiecte de sprijin în plus (efecte cel puțin „Epic”).",
"任何房间：领袖攻击 +{0}%。契合「武器」：伤害 +{1}%，每次攻击放出连锁闪电（跳 {2} 个敌人）。": "Orice cameră: atacul Liderului +{0}%. Se potrivește cu „Armă”: daune +{1}%, fiecare atac eliberează un fulger în lanț (sare prin {2} inamici).",
"任何房间：领袖每天回复 {0}% 生命（不需要医院）。契合「医疗 / 水域」：医院回复 +{1}%；水域武器射程 +{2}。": "Orice cameră: liderul își reface {0}% din viață pe zi (fără spital). Se potrivește cu „Medical / Apă”: vindecarea în spital +{1}%; raza armelor de apă +{2}.",
"任何房间：领袖每天获得 {0} 经验。契合「生产」：这个房间自己的产出 ×{1}。": "Orice cameră: liderul tău primește {0} EXP pe zi. Se potrivește cu „Producție”: producția proprie a acestei camere ×{1}.",
"任何房间：领袖每天获得 {0} 经验。契合「训练」：领袖出征得到的经验 +{1}%。": "Orice cameră: liderul tău primește {0} EXP pe zi. Se potrivește cu „Antrenament”: EXP-ul Liderului din expediții +{1}%.",
